import java.util.Scanner;
public class RecursiveBinarySearch {
    private static int search(int[] values,int target,int low,int high){if(low>high)return -1;int middle=low+(high-low)/2;if(values[middle]==target)return middle;if(target<values[middle])return search(values,target,low,middle-1);return search(values,target,middle+1,high);}
    public static void main(String[] args){Scanner in=new Scanner(System.in);System.out.print("Enter array size (1-100): ");if(!in.hasNextInt()){System.out.println("Enter a whole number from 1 to 100.");return;}int n=in.nextInt();if(n<1||n>100){System.out.println("Array size must be from 1 to 100.");return;}int[] a=new int[n];System.out.print("Enter sorted values: ");for(int i=0;i<n;i++){if(!in.hasNextInt()){System.out.println("Enter exactly "+n+" whole numbers and a target.");return;}a[i]=in.nextInt();if(i>0&&a[i]<a[i-1]){System.out.println("Values must be sorted in ascending order.");return;}}if(!in.hasNextInt()){System.out.println("Enter a target whole number.");return;}int target=in.nextInt();if(in.hasNext()){System.out.println("Enter only the values and one target.");return;}int index=search(a,target,0,n-1);System.out.println(index<0?"Not found":"Found at index "+index);}
}
